print('5xx stable='+stable.filter(r=>r.status>=500).length+' canary='+canary.filter(r=>r.status>=500).length);
print('non200 stable='+stable.filter(r=>r.status!==200).length+' canary='+canary.filter(r=>r.status!==200).length);
