for(const p of paths){
  const s=stable.filter(r=>r.path===p&&r.t>=60), c=canary.filter(r=>r.path===p&&r.t>=60);
  print('after60s '+p+'  canary n='+c.length+' p50='+pct(c.map(r=>r.ms),50)+' p95='+p95(c)+' p99='+p99(c)+' | stable n='+s.length+' p50='+pct(s.map(r=>r.ms),50)+' p95='+p95(s)+' p99='+p99(s));
}
