print('after60s ALL canary p95='+p95(cAll)+' p99='+p99(cAll)+' | stable p95='+p95(sAll)+' p99='+p99(sAll));
const c30=canary.filter(r=>r.t<30), s30=stable.filter(r=>r.t<30);
print('first30s ALL canary p95='+p95(c30)+' max='+Math.max(...c30.map(r=>r.ms))+' | stable p95='+p95(s30));

